output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles that are too narrow for two-way passage.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "must_reclaim_parked_cart",
    "text": "After parking or dropping a cart, the shopper is obliged to reclaim a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickupCart"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouths",
    "text": "Carts may only be parked at designated wide aisle mouths leading into pedestrian-only aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkingPoint": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingPoint"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_only_in_entrance_or_pedestrian_zone",
    "text": "Except at the entrance/cart bay, shoppers without carts should only be in pedestrian-only aisles or their adjacent cart-parking mouths.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingPoint": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessPermittedZone": {
          "or": [
            "entranceOrCartBay",
            "singleFileAisle",
            "cartParkingPoint"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessPermittedZone"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_service_locations",
    "text": "Interactions are only permitted either at cart-service points or at cells adjacent to shelves.",
    "abstraction": {
      "state_properties": {
        "cartServicePoint": {
          "or": [
            "at(1,7)",
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "shelfServicePoint": "adjShelf",
        "legalInteractionPoint": {
          "or": [
            "cartServicePoint",
            "shelfServicePoint"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "legalInteractionPoint"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_service_requires_cart",
    "text": "When servicing shelves from open aisles, shoppers are expected to have their cart with them.",
    "abstraction": {
      "state_properties": {
        "openAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        },
        "openShelfServiceCell": {
          "and": [
            "adjShelf",
            "openAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfServiceCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_shelf_service_hands_free",
    "text": "Shelf interactions inside single-file aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfCell": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfCell",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A shopper must not push a cart from an open aisle into a single-file pedestrian aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": "hasCart",
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  }
]
